/**
 * @description 批量软删的结果，部分成功语义：成功的 id 进入 `deleted_ids`，\n其余进入 `failed`，每条带 `id` 与 `reason`（鉴权 / 不存在 / 状态不可删 等）。\n外层 envelope 仍返回 200；调用方需检查 `failed` 是否为空。\n
 */
export const batchDeleteResultSchema = z.object({
    "deleted_ids": z.array(z.string()),
"failed": z.array(z.object({
    "id": z.string(),
"reason": z.string()
    }))
    }).describe("Batch soft-delete result with partial success: successful IDs go into `deleted_ids`; others go into `failed`, each with `id` and `reason` (authorization, missing resource, undeletable status, etc.). The outer envelope still returns 200; callers must check whether `failed` is empty.\n") as unknown as z.ZodType<BatchDeleteResult>

export const teamBatchDeleteRequestSchema = z.object({
    "team_ids": z.array(z.string()).min(1).max(100)
    }) as unknown as z.ZodType<TeamBatchDeleteRequest>

export const userBatchDeleteRequestSchema = z.object({
    "user_ids": z.array(z.string()).min(1).max(100)
    }) as unknown as z.ZodType<UserBatchDeleteRequest>

export const agentBatchDeleteRequestSchema = z.object({
    "agent_ids": z.array(z.string()).min(1).max(100)
    }) as unknown as z.ZodType<AgentBatchDeleteRequest>

export const taskBatchDeleteRequestSchema = z.object({
    "task_ids": z.array(z.string()).min(1).max(100)
    }) as unknown as z.ZodType<TaskBatchDeleteRequest>

/**
 * @description 团队主表（PRD §15.1 teams），并在 `/team/get` 响应里回填该团队\n当前的成员/资产 id 集合（`user_ids` / `agent_ids` / `task_ids`），\n作为 4 实体反向归属的唯一查询入口（替代被砍掉的 list 接口）。\n
 */
export const teamDataSchema = z.object({
    "team_id": z.string().describe("Globally unique team ID generated by the server on creation."),
"name": z.string().describe("Team name, unique within the tenant."),
"description": z.optional(z.string()),
"owner_user_id": z.string().describe("Team owner's user_id (must reference an existing user)."),
get "status"(){
                return teamStatusSchema
              },
"user_ids": z.optional(z.array(z.string()).describe("Current team member user_ids (active, including owner). **Authoritative write field for the Team↔User many-to-many relationship** via `TeamUpdateRequest.user_ids`; synchronized with reverse view `UserData.team_ids`. `/team/get` always populates it; create/update responses may omit it or return an empty array.\n")),
"agent_ids": z.optional(z.array(z.string()).describe("Current active Agent IDs in this team. **Authoritative write field for the Team↔Agent many-to-many relationship**, via `TeamUpdateRequest.agent_ids` or `AgentCreateRequest.team_id` on creation. The Agent's own `team_id` mirrors this membership. `/team/get` always populates it; create/update may omit it.\n")),
"task_ids": z.optional(z.array(z.string()).describe("Current non-archived Task IDs in this team. Read-only; like `user_ids`, always returned by `/team/get` but may be omitted from create/update responses.\n")),
"created_at": z.iso.datetime(),
"updated_at": z.iso.datetime()
    }).describe("Team master record (PRD §15.1 teams). `/team/get` fills current member/asset ID sets (`user_ids`, `agent_ids`, `task_ids`) as the sole reverse-membership lookup for the four entities, replacing removed list endpoints.\n") as unknown as z.ZodType<TeamData>

export const teamCreateRequestSchema = z.object({
    "name": z.string(),
"description": z.optional(z.string()),
"owner_user_id": z.string()
    }) as unknown as z.ZodType<TeamCreateRequest>

export const teamGetRequestSchema = z.object({
    "team_id": z.string()
    }) as unknown as z.ZodType<TeamGetRequest>

/**
 * @description PATCH 语义，仅更新传入字段。`user_ids` / `agent_ids` 为 Team↔User\n与 Team↔Agent 多对多关系的**写权威字段**：传入则整体替换该 Team\n当前关联集合，不传则保持不变，传空数组表示清空（owner 永远保留\n在 `user_ids` 内，移除 owner 须先 `owner_user_id` 转移）。\n
 */
export const teamUpdateRequestSchema = z.object({
    "team_id": z.string(),
"name": z.optional(z.string()),
"description": z.optional(z.string()),
"owner_user_id": z.optional(z.string().describe("Provide to transfer ownership; the new owner must be a team member.")),
"user_ids": z.optional(z.array(z.string()).max(200).describe("Complete set of team member user_ids, including owner. Replaces the set when supplied; omitted leaves it unchanged; empty means keep only the owner (server automatically includes the owner and forbids removal). Each user_id must exist. Synchronizes reverse view `UserData.team_ids`.\n")),
"agent_ids": z.optional(z.array(z.string()).max(200).describe("Complete set of current Agent IDs for this team. Supplied replaces all; omitted leaves unchanged; empty clears. Each agent_id must satisfy composite `(team_id, agent_id)` consistency (its existing team_id must equal this team), otherwise apply endpoint-wide 404/403 rules. Only establishes/removes agent-team associations; does not change other Agent fields.\n")),
get "status"(){
                return teamStatusSchema.optional()
              }
    }).describe("PATCH semantics: only supplied fields change. `user_ids` / `agent_ids` are **authoritative write fields** for Team↔User and Team↔Agent many-to-many relationships. Supplied replaces the team's set, omitted preserves it, empty clears it (owner always remains in user_ids; transfer owner_user_id before removing the old owner).\n") as unknown as z.ZodType<TeamUpdateRequest>

/**
 * @description 用户主表（PRD §15.2 users）。User 自身只承载身份信息（name /\njob_description / status）；与 Team / Task / Agent 的所有关联\n**写路径都在对方侧**（Team 由 `TeamUpdateRequest.user_ids` 维护\n成员、`TeamCreateRequest.owner_user_id` 写入首位 owner；Agent 写\n`owner_user_id`；Task 写 `creator_user_id`）。此处的 `team_ids` /\n`task_ids` / `owned_agent_ids` / `task_agent_ids` 均为**只读反查\n视图**，仅 `/user/get` 保证回填；create/update 响应可能为空数组\n或缺省。\n
 */
export const userDataSchema = z.object({
    "user_id": z.string().describe("User ID generated by the server on creation."),
"name": z.string().describe("Username/display name."),
"job_description": z.optional(z.string().describe("Job/position description (free text for Agent context).")),
"team_ids": z.optional(z.array(z.string()).describe("Team IDs this user belongs to. **Read-only reverse view**, guaranteed only by `/user/get`. Write through `TeamUpdateRequest.user_ids`.\n")),
"task_ids": z.optional(z.array(z.string()).describe("Task IDs associated with the user as creator or participant. **Read-only reverse view**, guaranteed only by `/user/get`. Write on the task side (`TaskCreateRequest.creator_user_id` / `TaskData.user_ids`).\n")),
"owned_agent_ids": z.optional(z.array(z.string()).describe("Agent IDs owned by this user (all Agents whose `AgentData.owner_user_id` points to this user). **Read-only reverse view**, guaranteed only by `/user/get`. Write through `AgentCreateRequest.owner_user_id` / `AgentUpdateRequest.owner_user_id`.\n")),
"task_agent_ids": z.optional(z.array(z.string()).describe("Agent IDs indirectly associated through `task_ids`: deduplicated union of `agent_ids` across participating Tasks. **Read-only derived field**, guaranteed only by `/user/get`.\n")),
get "status"(){
                return userStatusSchema
              },
"created_at": z.iso.datetime(),
"updated_at": z.iso.datetime()
    }).describe("User master record (PRD §15.2 users). User contains only identity fields (name / job_description / status). **All relationship writes are on the other entity**: Team membership via TeamUpdateRequest.user_ids and initial owner via TeamCreateRequest.owner_user_id; Agent via owner_user_id; Task via creator_user_id. team_ids / task_ids / owned_agent_ids / task_agent_ids here are **read-only reverse views**, guaranteed only by `/user/get`; create/update may omit them or return empty arrays.\n") as unknown as z.ZodType<UserData>

/**
 * @description 创建 user。仅承载身份信息；跨实体关联不在这里写——加入 Team\n通过 team 侧 owner 关系派生，关联 Agent 通过 `AgentCreateRequest\n.owner_user_id`，关联 Task 通过 `TaskCreateRequest.creator_user_id`\n/ `TaskCreateRequest.user_ids`。\n
 */
export const userCreateRequestSchema = z.object({
    "name": z.string(),
"job_description": z.optional(z.string())
    }).describe("Create a user with identity information only. Cross-entity relationships are written elsewhere: Team membership is derived from team-side ownership, Agent association through AgentCreateRequest.owner_user_id, and Task association through TaskCreateRequest.creator_user_id / TaskCreateRequest.user_ids.\n") as unknown as z.ZodType<UserCreateRequest>

/**
 * @description PATCH 语义，仅更新传入字段。跨实体关联同 `UserCreateRequest`，\n全部由对方侧承载，user 侧不接受关联写入。\n
 */
export const userUpdateRequestSchema = z.object({
    "user_id": z.string(),
"name": z.optional(z.string()),
"job_description": z.optional(z.string()),
get "status"(){
                return userStatusSchema.optional()
              }
    }).describe("PATCH semantics: update only supplied fields. As with UserCreateRequest, all cross-entity relationships are maintained on the other side; user endpoints reject relationship writes.\n") as unknown as z.ZodType<UserUpdateRequest>

export const userGetRequestSchema = z.object({
    "user_id": z.string()
    }) as unknown as z.ZodType<UserGetRequest>

/**
 * @description Agent 主表（PRD §15.4 agents）。`agent_id` 全局唯一、不可变；\n与 `team_id` 组成**复合唯一键** `(team_id, agent_id)`，即同一\n`agent_id` 不会出现在两个 `team_id` 下。\n
 */
export const agentDataSchema = z.object({
    "agent_id": z.string().describe("Globally unique Agent ID generated by the server on creation."),
"team_id": z.string().describe("Owning team (one team per Agent); forms globally unique composite key `(team_id, agent_id)` with agent_id.\n"),
"name": z.string().describe("Agent name, unique within the team."),
"description": z.optional(z.string().describe("One-sentence description.")),
"prompt": z.optional(z.string().describe("Responsibilities and behavioral constraints.")),
"owner_user_id": z.optional(z.string().describe("Agent owner's user_id. The **only write path** for Agent↔User ownership; synchronizes reverse view `UserData.owned_agent_ids`.\n")),
get "visibility"(){
                return agentVisibilitySchema.optional()
              },
get "status"(){
                return agentStatusSchema
              },
"task_ids": z.optional(z.array(z.string()).describe("Task IDs associated with this Agent. **Read-only reverse view**, guaranteed only by `/agent/get`. Write through TaskCreateRequest.agent_ids / TaskUpdateRequest.agent_ids.\n")),
"created_at": z.iso.datetime(),
"updated_at": z.iso.datetime()
    }).describe("Agent master record (PRD §15.4 agents). agent_id is globally unique and immutable; with team_id it forms the **unique composite key** `(team_id, agent_id)`, so the same agent_id cannot occur under two team_ids.\n") as unknown as z.ZodType<AgentData>

export const agentCreateRequestSchema = z.object({
    "team_id": z.string(),
"name": z.string(),
"description": z.optional(z.string()),
"prompt": z.optional(z.string()),
"owner_user_id": z.optional(z.string()),
get "visibility"(){
                return agentVisibilitySchema.optional()
              }
    }) as unknown as z.ZodType<AgentCreateRequest>

/**
 * @description 以 `agent_id` 全局唯一寻址。客户端可**可选**额外传 `team_id`\n以触发 `(team_id, agent_id)` 复合键一致性校验（不可见 → 404；\n可见但不匹配 → 403，规则同 `info.description`）。\n
 */
export const agentGetRequestSchema = z.object({
    "agent_id": z.string(),
"team_id": z.optional(z.string().describe("Optional; when supplied, validates composite-key consistency with agent_id.\n"))
    }).describe("Address by globally unique agent_id. Clients may **optionally** also provide team_id to validate `(team_id, agent_id)` consistency (invisible → 404; visible but mismatched → 403, as in info.description).\n") as unknown as z.ZodType<AgentGetRequest>

/**
 * @description PATCH 语义，仅更新传入字段。\n客户端可**可选**额外传 `team_id` 触发 `(team_id, agent_id)`\n复合键一致性校验（语义同 `AgentGetRequest`）。\n注意：`team_id` 不可作为更新目标（Agent 归属 team 不可变）；\n若与 `agent_id` 实际归属不一致按 403 处理。\n
 */
export const agentUpdateRequestSchema = z.object({
    "agent_id": z.string(),
"team_id": z.optional(z.string().describe("Optional; used only for composite-key consistency validation, not updates.\n")),
"name": z.optional(z.string()),
"description": z.optional(z.string()),
"prompt": z.optional(z.string()),
"owner_user_id": z.optional(z.string().describe("Optional; supplying this transfers ownership. The new owner must be a current member of the Agent's team, otherwise 422. Successful transfers refresh both users' UserData.owned_agent_ids reverse views.\n")),
get "visibility"(){
                return agentVisibilitySchema.optional()
              },
get "status"(){
                return agentStatusSchema.optional()
              }
    }).describe("PATCH semantics: update only supplied fields. Clients may **optionally** also supply team_id to validate `(team_id, agent_id)` consistency, as in AgentGetRequest. team_id cannot be updated (Agent team ownership is immutable); mismatch with actual ownership returns 403.\n") as unknown as z.ZodType<AgentUpdateRequest>

/**
 * @description Task 主表（PRD §15.5 tasks），含关联 Agent 与参与 User 列表。\nTask 是 User↔Task 与 Agent↔Task 两组多对多关系的**写权威侧**。\n
 */
export const taskDataSchema = z.object({
    "task_id": z.string().describe("Globally unique Task ID generated by the server on creation."),
"team_id": z.string(),
"creator_user_id": z.string().describe("Creator user_id, **required on creation and immutable**. Distinct from user_ids; the creator is automatically included in the user_ids reverse set.\n"),
"title": z.optional(z.string()),
"description": z.optional(z.string()),
get "source_type"(){
                return taskSourceTypeSchema.optional()
              },
"source_url": z.optional(z.string()),
"agent_ids": z.optional(z.array(z.string()).describe("Agent IDs associated with this Task. Each agent_id must satisfy `(team_id, agent_id)` consistency with this Task's team_id; otherwise apply endpoint-wide rules (invisible → 404; visible but ownership mismatch → 403).\n")),
"user_ids": z.optional(z.array(z.string()).describe("Participating user_ids associated with this Task, excluding creator_user_id (stored separately). **Authoritative write field** for User↔Task many-to-many membership; synchronizes UserData.task_ids. Each user_id must be a current member of the Task's team.\n")),
"created_at": z.iso.datetime(),
"updated_at": z.iso.datetime()
    }).describe("Task master record (PRD §15.5 tasks), including associated Agents and participating Users. Task is the **authoritative write side** for User↔Task and Agent↔Task many-to-many relationships.\n") as unknown as z.ZodType<TaskData>

export const taskCreateRequestSchema = z.object({
    "team_id": z.string().describe("Owning team; **required on creation and immutable** (absent from updates)."),
"creator_user_id": z.string().describe("Creator user_id; **required on creation and immutable** (absent from updates). Must be a current member of team_id's team.\n"),
"title": z.optional(z.string()),
"description": z.optional(z.string()),
get "source_type"(){
                return taskSourceTypeSchema.optional()
              },
"source_url": z.optional(z.string().describe("Source link; same SSRF allowlist as WikiCreateRequest.source_url.")),
"agent_ids": z.optional(z.array(z.string()).max(50).describe("Optional Agent IDs to associate on creation. Each must satisfy `(team_id, agent_id)` consistency with team_id, otherwise endpoint-wide 404/403 rules apply.\n")),
"user_ids": z.optional(z.array(z.string()).max(50).describe("Optional participating user_ids to associate on creation, excluding the creator (stored separately in creator_user_id). Each user_id must be a current member of team_id's team, otherwise 422.\n"))
    }) as unknown as z.ZodType<TaskCreateRequest>

export const taskGetRequestSchema = z.object({
    "task_id": z.string()
    }) as unknown as z.ZodType<TaskGetRequest>

/**
 * @description PATCH 语义，仅更新传入字段。`team_id` 与 `creator_user_id` **不\n可改**（请求体不接受这两个字段）；如需变更归属请走删除重建。\n
 */
export const taskUpdateRequestSchema = z.object({
    "task_id": z.string(),
"title": z.optional(z.string()),
"description": z.optional(z.string()),
get "source_type"(){
                return taskSourceTypeSchema.optional()
              },
"source_url": z.optional(z.string()),
"agent_ids": z.optional(z.array(z.string()).max(50).describe("Supplied replaces the Task's entire associated Agent set; omitted preserves it; empty clears it. Each agent_id must satisfy `(team_id, agent_id)` consistency with the Task's team_id, otherwise endpoint-wide 404/403 rules apply.\n")),
"user_ids": z.optional(z.array(z.string()).max(50).describe("Supplied replaces the Task's entire participating User set, excluding the creator; omitted preserves it; empty clears it. Each user_id must be a current member of the Task's team, otherwise 422.\n"))
    }).describe("PATCH semantics: update only supplied fields. team_id and creator_user_id are **immutable** and rejected in the request body; delete and recreate to change ownership.\n") as unknown as z.ZodType<TaskUpdateRequest>

